-- RLS cleanup preserving published public reads and admin-only writes.
DROP POLICY IF EXISTS "movies_admin_select" ON public.movies;
DROP POLICY IF EXISTS "Profiles are viewable by their owner" ON public.profiles;
DROP POLICY IF EXISTS "Admins manage episodes" ON public.episodes;
CREATE POLICY "Admins insert episodes" ON public.episodes FOR INSERT TO authenticated WITH CHECK ((SELECT public.is_site_admin()));
CREATE POLICY "Admins update episodes" ON public.episodes FOR UPDATE TO authenticated USING ((SELECT public.is_site_admin())) WITH CHECK ((SELECT public.is_site_admin()));
CREATE POLICY "Admins delete episodes" ON public.episodes FOR DELETE TO authenticated USING ((SELECT public.is_site_admin()));
DROP POLICY IF EXISTS "Admins manage seasons" ON public.seasons;
CREATE POLICY "Admins insert seasons" ON public.seasons FOR INSERT TO authenticated WITH CHECK ((SELECT public.is_site_admin()));
CREATE POLICY "Admins update seasons" ON public.seasons FOR UPDATE TO authenticated USING ((SELECT public.is_site_admin())) WITH CHECK ((SELECT public.is_site_admin()));
CREATE POLICY "Admins delete seasons" ON public.seasons FOR DELETE TO authenticated USING ((SELECT public.is_site_admin()));
DROP POLICY IF EXISTS "Admin category access" ON public.site_categories;
CREATE POLICY "Admin insert categories" ON public.site_categories FOR INSERT TO authenticated WITH CHECK ((SELECT public.is_site_admin()));
CREATE POLICY "Admin update categories" ON public.site_categories FOR UPDATE TO authenticated USING ((SELECT public.is_site_admin())) WITH CHECK ((SELECT public.is_site_admin()));
CREATE POLICY "Admin delete categories" ON public.site_categories FOR DELETE TO authenticated USING ((SELECT public.is_site_admin()));
DROP POLICY IF EXISTS "Visitors can post named comments" ON public.comments;
CREATE POLICY "Visitors can post named comments" ON public.comments FOR INSERT TO anon WITH CHECK (user_id IS NULL AND length(btrim(author_name)) BETWEEN 1 AND 80 AND length(btrim(body)) BETWEEN 1 AND 2000 AND ((movie_id IS NOT NULL AND episode_id IS NULL) OR (movie_id IS NULL AND episode_id IS NOT NULL)));
DROP POLICY IF EXISTS "Published movies are public" ON public.movies;
CREATE POLICY "Published movies are public" ON public.movies FOR SELECT TO anon, authenticated USING (published = true OR (SELECT public.is_site_admin()));
DROP POLICY IF EXISTS "Public can view published episodes" ON public.episodes;
CREATE POLICY "Public can view published episodes" ON public.episodes FOR SELECT TO anon, authenticated USING ((published = true AND EXISTS (SELECT 1 FROM public.movies m WHERE m.id = episodes.series_id AND m.published = true)) OR (SELECT public.is_site_admin()));
DROP POLICY IF EXISTS "Public can view published seasons" ON public.seasons;
CREATE POLICY "Public can view published seasons" ON public.seasons FOR SELECT TO anon, authenticated USING (EXISTS (SELECT 1 FROM public.movies m WHERE m.id = seasons.series_id AND m.published = true AND m.content_type = 'series') OR (SELECT public.is_site_admin()));
DROP POLICY IF EXISTS "Public active categories" ON public.site_categories;
CREATE POLICY "Public active categories" ON public.site_categories FOR SELECT TO anon, authenticated USING (is_active OR (SELECT public.is_site_admin()));
DROP POLICY IF EXISTS "Public can read visible comments" ON public.comments;
CREATE POLICY "Public can read visible comments" ON public.comments FOR SELECT TO anon, authenticated USING (is_hidden = false OR (SELECT public.is_site_admin()));
DROP POLICY IF EXISTS "Authors or admins can delete comments" ON public.comments;
CREATE POLICY "Authors or admins can delete comments" ON public.comments FOR DELETE TO authenticated USING (user_id = (SELECT auth.uid()) OR (SELECT public.is_site_admin()));
DROP POLICY IF EXISTS "Only admins can moderate comments" ON public.comments;
CREATE POLICY "Only admins can moderate comments" ON public.comments FOR UPDATE TO authenticated USING ((SELECT public.is_site_admin())) WITH CHECK ((SELECT public.is_site_admin()));
DROP POLICY IF EXISTS "profiles_select_self_or_admin" ON public.profiles;
CREATE POLICY "profiles_select_self_or_admin" ON public.profiles FOR SELECT TO authenticated USING (id = (SELECT auth.uid()) OR (SELECT public.is_site_admin()));
DROP POLICY IF EXISTS "Users can update their own profile" ON public.profiles;
CREATE POLICY "Users can update their own profile" ON public.profiles FOR UPDATE TO authenticated USING (id = (SELECT auth.uid()) OR (SELECT public.is_site_admin())) WITH CHECK (id = (SELECT auth.uid()) OR (SELECT public.is_site_admin()));
DROP POLICY IF EXISTS "Users view own watch history" ON public.watch_history;
CREATE POLICY "Users view own watch history" ON public.watch_history FOR SELECT TO authenticated USING (user_id = (SELECT auth.uid()) OR (SELECT public.is_site_admin()));
